<script setup>
import {ref,reactive,computed,onMounted,onBeforeUnmount} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import mqtt from 'mqtt';
import {account,api,restoreAccount} from './account';
import {userKey,requestId,deviceKey,deviceEntry,localDevices,topics,applyMessage,command} from './deviceProtocol';
import ThemeToggle from './components/ThemeToggle.vue';
import LegacyControl from './components/LegacyControl.vue';
const route=useRoute(),router=useRouter();
const page=ref('home'),thirdParty=ref(route.name==='Guest'),list=ref([]),selected=ref(''),states=reactive({}),connected=ref(false),error=ref(''),notice=ref(''),busy=ref(false),now=ref(Date.now());
const connection=reactive({host:`${location.protocol==='https:'?'wss':'ws'}://${location.host}/mqtt`,username:'',password:''});
const addForm=reactive({mac:'',model:'tc1',version:'v2'}),newPassword=ref(''),oldPassword=ref('');
const active=computed(()=>{const d=list.value.find(x=>deviceKey(x)===selected.value);return d?{...states[deviceKey(d)],...d}:null;});
const fresh=computed(()=>connected.value && active.value?.available!==false && active.value?.sensor_valid && now.value-active.value.sensorAt<15000);
let client,timer,poll;
function disconnect(){client?.end(true);client=null;connected.value=false;Object.keys(states).forEach(k=>delete states[k]);}
function subscribe(){if(thirdParty.value)client?.subscribe(`phicomm/v2/${connection.username?userKey(connection.username):'local'}/discovery/+`,{qos:1});for(const d of list.value.filter(d=>!d.status||d.status==='active'))client?.subscribe(topics(d),{qos:1},(e,g)=>{if(e||g?.some(x=>x.qos===128))error.value='订阅被拒绝，请检查账号与设备归属';});}
async function refresh(){try{list.value=(thirdParty.value?localDevices().map(d=>({...d,username:connection.username})):await api('/devices')).map(deviceEntry);if(!list.value.some(d=>deviceKey(d)===selected.value))selected.value=list.value[0]?deviceKey(list.value[0]):'';if(connected.value)subscribe();}catch(e){error.value=e.message;}}
function connect(){disconnect();error.value='';if(!/^wss?:\/\//.test(connection.host)){error.value='请输入 ws:// 或 wss:// 地址';return;}busy.value=true;
 client=mqtt.connect(connection.host,{username:connection.username,password:connection.password,clientId:'web_'+requestId(),connectTimeout:5000,reconnectPeriod:3000,clean:true});
 client.on('connect',()=>{connected.value=true;busy.value=false;subscribe();for(const d of list.value)if(d.version==='v2')sendTo(d,'status.get');});
 client.on('close',()=>{connected.value=false;busy.value=false;});client.on('error',()=>{error.value='MQTT 连接失败，请检查地址、凭据和权限';busy.value=false;});
 client.on('message',(topic,payload)=>{if(thirdParty.value && topic.startsWith(`phicomm/v2/${connection.username?userKey(connection.username):'local'}/discovery/`)){try{const a=JSON.parse(payload.toString());if(a.protocol!=='tmcp'||a.protocol_version!==2||a.version!=='v2')return;const d=deviceEntry({mac:topic.split('/')[4],model:a.model,version:'v2',username:connection.username});if(!list.value.some(x=>deviceKey(x)===deviceKey(d))){list.value.push(d);localStorage.setItem('phicomm_devices',JSON.stringify(list.value));if(!selected.value)selected.value=deviceKey(d);subscribe();sendTo(d,'status.get');}}catch{}return;}for(const d of list.value){const s=states[deviceKey(d)] ||= {};if(applyMessage(d,s,topic,payload.toString())){if(topic.endsWith('/result'))notice.value=`${s.result?.message || s.result?.code || ''}`;break;}}});
 if(thirdParty.value)localStorage.setItem('tmcp_broker',JSON.stringify({host:connection.host,username:connection.username}));
}
function sendTo(d,action,params={}){if(!connected.value){error.value='请先连接 MQTT';return;}const id=requestId(),s=states[deviceKey(d)] ||= {}; (s.pending ||= {})[id]=action;const c=command(d,{action,params,request_id:id});client.publish(c.topic,c.payload,{qos:1,retain:false},e=>{if(e)error.value='发送失败';});}
function send(action,params={}){if(active.value)sendTo(active.value,action,params);}
function legacy(cmd){if(!connected.value){error.value='请先连接 MQTT';return;}const c=command(active.value,cmd);client.publish(c.topic,c.payload,{qos:1,retain:false});}
async function changeMode(){disconnect();notice.value='';error.value='';if(thirdParty.value){Object.assign(connection,{host:`${location.protocol==='https:'?'wss':'ws'}://${location.host}/mqtt`,username:'',password:''},JSON.parse(localStorage.getItem('tmcp_broker')||'{}'));}else{const s=await api('/register/status');Object.assign(connection,{host:s.mqtt_ws_uri||`${location.protocol==='https:'?'wss':'ws'}://${location.host}/mqtt`,username:account.mqttUsername||account.username,password:account.password||''});}await refresh();}
async function add(){try{const d=deviceEntry({...addForm,version:addForm.model==='tc1'?addForm.version:'v2',...(thirdParty.value?{username:connection.username}:{})});if(thirdParty.value){if(list.value.some(x=>x.mac===d.mac))throw Error('设备已存在');localStorage.setItem('phicomm_devices',JSON.stringify([...list.value,d]));}else await api('/devices',{method:'POST',body:JSON.stringify(d)});await refresh();addForm.mac='';}catch(e){error.value=e.message;}}
async function remove(d){if(!confirm(`移除 ${d.mac}？`))return;try{client?.unsubscribe(topics(d));if(thirdParty.value)localStorage.setItem('phicomm_devices',JSON.stringify(list.value.filter(x=>deviceKey(x)!==deviceKey(d))));else await api(`/devices/${d.namespace?'scoped/':''}${d.mac}${d.namespace?'?mqtt_username='+encodeURIComponent(d.mqtt_username||d.username):''}`,{method:'DELETE'});await refresh();}catch(e){error.value=e.message;}}
async function logout(){try{await api('/auth/logout',{method:'POST',body:'{}'});}catch(e){error.value=e.message;}account.username=null;account.mqttUsername=null;account.isAdmin=false;account.aliases=[];account.password='';disconnect();await router.replace('/login');}
async function changePassword(){try{await api('/auth/password',{method:'POST',body:JSON.stringify({current_password:oldPassword.value,password:newPassword.value})});await logout();}catch(e){error.value=e.message;}}
onMounted(async()=>{if(route.name!=='Guest')await restoreAccount();await changeMode();if(!thirdParty.value&&connection.password)connect();timer=setInterval(()=>now.value=Date.now(),1000);poll=setInterval(()=>{if(!thirdParty.value&&!document.hidden)refresh();},5000);});
onBeforeUnmount(()=>{disconnect();clearInterval(timer);clearInterval(poll);});
</script>
<template>
<main class="console-page">
<header class="console-topbar"><div class="brand">Phicomm <span class="brand-subtitle">TMCP</span></div><nav class="console-nav"><span class="status-pill" :class="{online:connected}">{{connected?'MQTT 已连接':'MQTT 未连接'}}</span><ThemeToggle/><button v-if="account.username" @click="logout">退出</button><RouterLink v-else to="/login">登录</RouterLink></nav></header>
<nav class="platform-tabs" aria-label="主导航"><button :aria-current="page==='home'?'page':undefined" @click="page='home'">首页</button><button :aria-current="page==='settings'?'page':undefined" @click="page='settings'">设置</button></nav>
<p v-if="error" role="alert" class="feedback error">{{error}}</p><p v-if="notice" role="status" class="feedback">{{notice}}</p>
<template v-if="page==='home'">
<div class="page-heading"><div><h1>我的设备</h1><p>{{thirdParty?'自建 Broker':account.username}} · {{list.length}} 台设备</p></div><button @click="refresh">刷新</button></div>
<div class="dashboard-grid"><aside class="surface devices-panel"><h2>设备</h2><ul class="device-list"><li v-for="d in list" :key="deviceKey(d)"><button class="device-select" :aria-pressed="selected===deviceKey(d)" @click="selected=deviceKey(d)"><span><b>{{d.model.toUpperCase()}}</b><small class="device-mac">{{d.mac}}</small><small>{{d.version==='v1'?'Legacy':'TMCP'}}</small></span></button></li></ul><p v-if="!list.length" class="helper-text">暂无设备。TMCP 设备上线后自动发现，或在设置中添加。</p></aside>
<div v-if="active" class="device-area"><div class="device-area-heading"><h2>{{active.name||active.model.toUpperCase()}}</h2><span>{{!connected?'未连接':active.available===false?'离线':active.available===true?'在线':'状态未知'}}</span><button v-if="active.version==='v2'" :disabled="!connected" @click="send('status.get')">刷新状态</button></div>
<LegacyControl v-if="active.version==='v1'" :device="active" :connected="connected" @send-cmd="legacy"/>
<section v-else class="surface platform-core">
<template v-if="active.model==='m1'"><p v-if="!fresh" class="helper-text">传感器数据无效或已过期</p><dl class="sensor-grid"><div v-for="[key,title,unit] in [['temperature','温度','°C'],['humidity','湿度','%'],['pm25','PM2.5','µg/m³'],['formaldehyde','甲醛','mg/m³']]" :key="key"><dt>{{title}}</dt><dd>{{fresh?active[key]:'—'}} <small>{{unit}}</small></dd></div></dl><label>屏幕亮度<select :value="active.brightness_requested*25" :disabled="!connected" @change="send('display.set',{brightness:Number($event.target.value)})"><option v-for="n in 5" :value="(n-1)*25">{{(n-1)*25}}%</option></select></label></template>
<template v-else-if="active.model==='tc1'"><dl class="sensor-grid"><div><dt>功率</dt><dd>{{active.power_watts??'—'}} W</dd></div><div><dt>累计电量</dt><dd>{{active.energy_kwh??'—'}} kWh</dd></div></dl><div class="outlet-grid"><button v-for="n in 6" :disabled="!connected" @click="send('outlet.set',{index:n-1,on:!active.socket_states?.[n-1]})">{{active.socket_names?.[n-1]||`插座 ${n}`}} · {{active.socket_states?.[n-1]?'开':'关'}}</button></div></template>
<template v-else><h3>风机</h3><p>{{active.fan_on?'运行':'停止'}} · {{active.speed??'—'}}%</p><button :disabled="!connected" @click="send('fan.set',{on:!active.requested_fan_on})">{{active.fan_on?'停止':'启动'}}</button><label>风速<input type="range" min="0" max="100" :value="active.speed" :disabled="!connected" @change="send('fan.set',{speed:Number($event.target.value)})"/></label><h3>灯环</h3><button :disabled="!connected" @click="send('light.set',{enabled:!active.led_enabled})">切换灯环</button><h3>多设备平均值</h3><p>{{active.average?.valid?`${active.average.temperature} °C · ${active.average.humidity}% · PM2.5 ${active.average.pm25}`:'暂无有效样本'}}</p></template>
</section></div><section v-else class="surface empty-control"><h2>从一台设备开始</h2><p>在设置中连接 Broker 并添加设备。</p><button @click="page='settings'">打开设置</button></section></div>
</template>
<template v-else>
<div class="page-heading"><div><h1>设置</h1><p>连接、设备与账号</p></div><button @click="page='home'">返回首页</button></div>
<section class="surface platform-core"><h2>MQTT 连接</h2><label v-if="account.username">连接模式<select v-model="thirdParty" @change="changeMode"><option :value="false">平台 Broker</option><option :value="true">第三方 Broker</option></select></label><form @submit.prevent="connect"><label>WebSocket 地址<input v-model="connection.host" :disabled="connected||!thirdParty" required/></label><label>MQTT 用户名<input v-model="connection.username" :disabled="connected||!thirdParty" autocomplete="username"/></label><label>MQTT 密码<input v-model="connection.password" :disabled="connected" type="password" autocomplete="current-password"/></label><p class="helper-text">密码仅保留在页面内存。自建 Broker 需要支持 MQTT WebSocket。</p><button :disabled="busy||connected">{{busy?'连接中…':'连接'}}</button><button type="button" @click="disconnect" :disabled="!connected">断开</button></form></section>
<section class="surface platform-core"><h2>设备管理</h2><p class="helper-text">TMCP 设备使用同一 MQTT 账号上线后自动发现。Legacy 仅支持 TC1。</p><form @submit.prevent="add"><label>MAC<input v-model="addForm.mac" required placeholder="AABBCCDDEEFF"/></label><label>型号<select v-model="addForm.model"><option value="tc1">TC1</option><option value="m1">M1</option><option value="a1">A1</option></select></label><label v-if="addForm.model==='tc1'">协议<select v-model="addForm.version"><option value="v2">TMCP</option><option value="v1">Legacy</option></select></label><button>添加设备</button></form><div v-for="d in list" :key="deviceKey(d)" class="section-heading"><span>{{d.model.toUpperCase()}} · {{d.mac}} · {{d.version==='v1'?'Legacy':'TMCP'}}</span><button @click="remove(d)">移除</button></div></section>
<section v-if="account.username" class="surface platform-core"><h2>账号安全</h2><form @submit.prevent="changePassword"><label>当前密码<input v-model="oldPassword" type="password" required autocomplete="current-password"/></label><label>新密码<input v-model="newPassword" type="password" required minlength="6" autocomplete="new-password"/></label><button>修改密码并退出</button></form><RouterLink v-if="account.isAdmin" to="/admin">平台管理</RouterLink></section>
</template>
<footer class="console-footer">Phicomm · TMCP</footer></main>
</template>
